def count_even_numbers(numbers):
    # Time Complexity: O(n)
    # Space Complexity: O(1)
    count = 0
    for num in numbers:
        if num % 2 == 0:
            count += 1
    return count

def find_duplicates(arr):
    # Time Complexity: O(n)
    # Space Complexity: O(n) in the worst case
    seen = set()
    duplicates = set()
    result = []
    for item in arr:
        if item in seen:
            if item not in duplicates:
                duplicates.add(item)
                result.append(item)
        else:
            seen.add(item)
    return result

