# Preferred: Approach A (hash map)
# Justification: Sorting is O(n log n), while a single hash-map pass is O(n).
# For 10 million records, O(n) is significantly faster.

def most_frequent_zone(zones):
    freq = {}
    for zone in zones:
        freq[zone] = freq.get(zone, 0) + 1
    # O(n) time, O(k) space where k is number of unique zones
    max_zone = None
    max_count = 0
    for zone, count in freq.items():
        if count > max_count:
            max_count = count
            max_zone = zone
    return max_zone

